import { _ as _export_sfc, o as openBlock, c as createElementBlock, a3 as createStaticVNode } from "./chunks/framework.CGt8wd3h.js";
const __pageData = JSON.parse('{"title":"18. GS1 implementation models","description":"","frontmatter":{},"headers":[],"relativePath":"18-gs1-implementation-models.md","filePath":"18-gs1-implementation-models.md"}');
